pub const FIELDS: &str = "<field>";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Handle {
    pub function: String,
    pub value: String,
    pub ty: Ty,
    pub internal: bool,
    pub position: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Forced {
    pub key: String,
    pub why: String,
    pub fallback: Option<Fallback>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Slots {
    pub declared_here: collections::BTreeSet<String>,
    pub handles: collections::BTreeMap<String, Handle>,
    pub index: collections::BTreeMap<String, i64>,
    pub parent: Vec<i64>,
    pub forced: Vec<Forced>,
    pub duplicated: Vec<(String, String)>,
    pub held_together: Vec<String>,
    pub copies: Vec<(String, String)>,
}

impl Slots {
    pub fn new(declared_here: collections::BTreeSet<String>) -> Slots { Slots { declared_here, handles: collections::BTreeMap::new(), index: collections::BTreeMap::new(), parent: vec![], forced: vec![], duplicated: vec![], held_together: vec![], copies: vec![] } }
    pub fn id(&mut self, key: &str) -> i64 {
        let found = *nikaia_std::index::get(&self.index, key);
        if found.is_some() { return nikaia_std::index::or(found, || 0); }
        let fresh = self.parent.len() as i64;
        self.parent.push(fresh);
        self.index.insert(key.to_owned(), fresh);
        fresh
    }
    pub fn root(&mut self, start: i64) -> i64 {
        let mut at = start;
        while *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at)) != at {
            let up = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at));
            { let __nikaia_stored = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(up)); nikaia_std::index::set(&mut self.parent, nikaia_std::index::at(at), __nikaia_stored); }
            at = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at));
        }
        at
    }
    pub fn class_of(&mut self, key: &str) -> i64 {
        let id = self.id(key);
        self.root(id)
    }
    pub fn join(&mut self, left: &str, right: &str) {
        let one = self.class_of(left);
        let other = self.class_of(right);
        if one != other { { let __nikaia_stored = other; nikaia_std::index::set(&mut self.parent, nikaia_std::index::at(one), __nikaia_stored); } }
    }
    pub fn note(&mut self, function: &str, value: &str, ty: Ty, internal: bool, position: bool) {
        let key = slot(function, value);
        self.id(&key);
        if !self.handles.contains_key(&key) { self.handles.insert(key.to_owned(), Handle { function: function.to_owned(), value: value.to_owned(), ty, internal, position }); }
    }
    pub fn force(&mut self, function: &str, value: &str, why: String, fallback: Option<Fallback>) {
        let key = slot(function, value);
        self.id(&key);
        self.forced.push(Forced { key, why, fallback });
    }
    pub fn duplicates(&mut self, function: &str, value: &str, site: String) {
        let key = slot(function, value);
        self.id(&key);
        self.duplicated.push((key, site));
    }
    pub(crate) fn foreign_slots_hold_the_floor(&mut self) {
        let field_prefix = format!("{}::", FIELDS);
        let mut foreign: Vec<(String, String)> = vec![];
        for key in self.index.keys() {
            if !key.contains("::") { continue; }
            let mut owner = before_last(key, "::");
            let mut named = key.to_owned();
            if key.starts_with(&field_prefix) {
                let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
                named = (*nikaia_std::index::get(&parts, 1)).to_owned();
                owner = before_last(&named, ".");
            }
            if !self.declared_here.contains(&owner) { foreign.push((key.to_owned(), named)); }
        }
        for (key, named) in foreign.iter() {
            let why = format!("`{}` belongs to another file of this package, and that file's own pass decides its count - this one reads only one of the two", named);
            self.forced.push(Forced { key: key.to_owned(), why, fallback: Some(Fallback::ForeignFile) });
        }
    }
}

pub(crate) fn before_last(text: &str, separator: &str) -> String {
    let parts: Vec<&str> = text.split(separator).collect::<Vec<_>>();
    if parts.len() < 2 { return text.to_owned(); }
    let mut kept: Vec<String> = vec![];
    for i in 0..parts.len() as i64 - 1 { kept.push((*nikaia_std::index::get(&parts, (i) as usize)).to_owned()); }
    kept.join(separator)
}

pub fn decided(slots: &mut Slots) -> Sharing {
    slots.foreign_slots_hold_the_floor();
    let mut why_of: collections::BTreeMap<i64, String> = collections::BTreeMap::new();
    let mut fallback_of: collections::BTreeMap<i64, Fallback> = collections::BTreeMap::new();
    let mut floor: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let forced = slots.forced.to_owned();
    for one in forced.iter() {
        let root = slots.class_of(&one.key);
        if one.fallback.is_some() { floor.insert(root); }
        if !why_of.contains_key(&root) || fallback_of.contains_key(&root) && one.fallback.is_none() {
            why_of.insert(root, one.why.to_owned());
            set_fallback(&mut fallback_of, root, one.fallback);
        }
    }
    let mut held: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let together = slots.held_together.to_owned();
    for key in together.iter() { held.insert(slots.class_of(key)); }
    let keys: Vec<String> = handle_keys(&slots);
    let mut not_a_word: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for key in keys.iter() {
        let root = slots.class_of(key);
        if !holds_a_word(&handle_type(&slots, key)) { not_a_word.insert(root); }
    }
    let duplicated = sites_by_slot(&slots.duplicated);
    let copied_out = sites_by_slot(&slots.copies);
    let mut decisions: Vec<Decision> = vec![];
    let mut counts: collections::BTreeMap<String, Count> = collections::BTreeMap::new();
    let mut classes: collections::BTreeMap<String, collections::BTreeMap<i64, Class>> = collections::BTreeMap::new();
    for key in keys.iter() {
        let root = slots.class_of(key);
        let handle = match match *nikaia_std::index::get(&slots.handles, key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        let a_word = !not_a_word.contains(&root);
        let mut count = Count::Plain;
        let mut why: Option<String> = None;
        let mut fallback: Option<Fallback> = None;
        if why_of.contains_key(&root) {
            why = match *nikaia_std::index::get(&why_of, &root) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            fallback = nikaia_std::index::or_maybe(*nikaia_std::index::get(&fallback_of, &root), || None);
            count = Count::Atomic;
            if fallback.is_none() && a_word && !floor.contains(&root) && !held.contains(&root) { count = Count::Word; }
        }
        if handle.position { put_in_class(&mut classes, &handle.function, root, &handle.value, count); }
        counts.insert(key.to_owned(), count);
        if !handle.internal {
            decisions.push(Decision { function: handle.function.to_owned(), value: handle.value.to_owned(), ty: handle.ty.text(), count, why, fallback, duplications: nikaia_std::index::or(match *nikaia_std::index::get(&duplicated, key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()), copied_out: nikaia_std::index::or(match *nikaia_std::index::get(&copied_out, key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()), kept_its_lock: lock_kept(&count, a_word, held.contains(&root)) });
        }
    }
    let mut summaries: collections::BTreeMap<String, Vec<Class>> = collections::BTreeMap::new();
    for (function, roots) in classes.iter() {
        let mut found: Vec<Class> = vec![];
        for (_, class) in roots.iter() { found.push(Class { members: sorted_once(&class.members), count: class.count }); }
        summaries.insert(function.to_owned(), in_class_order(&found));
    }
    Sharing { decisions, summaries, counts }
}

pub(crate) fn set_fallback(fallback_of: &mut collections::BTreeMap<i64, Fallback>, root: i64, fallback: Option<Fallback>) {
    fallback_of.remove(&root);
    let row = match fallback { Some(__nikaia_value) => __nikaia_value, None => return };
    fallback_of.insert(root, row);
}

pub(crate) fn handle_keys(slots: &Slots) -> Vec<String> {
    let mut keys: Vec<String> = vec![];
    for key in slots.handles.keys() { keys.push(key.to_owned()); }
    keys
}

pub(crate) fn handle_type(slots: &Slots, key: &str) -> Ty {
    let handle = match *nikaia_std::index::get(&slots.handles, key) { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    handle.ty.clone()
}

pub(crate) fn sites_by_slot(pairs: &[(String, String)]) -> collections::BTreeMap<String, Vec<String>> {
    let mut out: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (key, site) in pairs.iter() {
        let mut sites = nikaia_std::index::or(match *nikaia_std::index::get(&out, key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        if !nikaia_std::list::contains(&sites, &site) { sites.push(site.to_owned()); }
        out.insert(key.to_owned(), sites);
    }
    out
}

pub(crate) fn put_in_class(classes: &mut collections::BTreeMap<String, collections::BTreeMap<i64, Class>>, function: &str, root: i64, member: &str, count: Count) {
    let mut roots = nikaia_std::index::or(match *nikaia_std::index::get(&classes, function) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeMap::new().into());
    let mut class = nikaia_std::index::or(match *nikaia_std::index::get(&roots, &root) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Class { members: vec![], count });
    class.members.push(member.to_owned());
    class.count = class.count.join(count);
    roots.insert(root, class);
    classes.insert(function.to_owned(), roots);
}

pub(crate) fn lock_kept(count: &Count, a_word: bool, held_together: bool) -> Option<String> {
    if *count != Count::Atomic || !a_word { return None; }
    if held_together { return Some(String::from("a word, but a door over several locks takes it, and a compare-and-swap cannot be held, so it keeps its lock")); }
    Some(String::from("a word, but the floor answered for it rather than a crossing, so it keeps its lock"))
}

pub(crate) fn sorted_once(members: &[String]) -> Vec<String> {
    let mut sorted = members.to_owned();
    sorted.sort();
    let mut out: Vec<String> = vec![];
    for one in sorted.iter() { if out.is_empty() || *nikaia_std::index::get(&out, nikaia_std::index::at(out.len() as i64 - 1)) != *one { out.push(one.to_owned()); } }
    out
}

pub(crate) fn in_class_order(classes: &[Class]) -> Vec<Class> {
    let mut out: Vec<Class> = vec![];
    for class in classes.iter() {
        let mut at = out.len() as i64;
        while at > 0 && class_before(class, nikaia_std::index::get(&out, nikaia_std::index::at(at - 1))) { at -= 1; }
        out.insert(nikaia_std::count::of(at), class.clone());
    }
    out
}

pub(crate) fn class_before(a: &Class, b: &Class) -> bool {
    let shorter = if (a.members.len() as i64) < b.members.len() as i64 { a.members.len() as i64 } else { b.members.len() as i64 };
    for i in 0..shorter { if *nikaia_std::index::get(&a.members, (i) as usize) != *nikaia_std::index::get(&b.members, (i) as usize) { return AsRef::<str>::as_ref(&(*nikaia_std::index::get(&a.members, (i) as usize))) < AsRef::<str>::as_ref(&(*nikaia_std::index::get(&b.members, (i) as usize))); } }
    if (a.members.len() as i64) != b.members.len() as i64 { return (a.members.len() as i64) < b.members.len() as i64; }
    a.count.rank() < b.count.rank()
}

pub(crate) const PARALLEL: [&str; 4] = ["par_iter", "par_pieces", "par_fold", "par_map"];

pub fn declared_here(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, .. } => {
                let name = *name;
                out.insert(names.resolve(name).to_owned());
            },
            Item::Enum { name, .. } => {
                let name = *name;
                out.insert(names.resolve(name).to_owned());
            },
            Item::Fn { name, .. } => {
                let name = *name;
                let own = a_symbols_text(names, name);
                if !own.is_empty() { out.insert(own); }
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    let own = method_name(names, &method.node);
                    if !own.is_empty() { out.insert(format!("{}::{}", owner, own)); }
                }
                out.insert(owner);
            },
            _ => { },
        }
    }
    out
}

pub(crate) fn method_name(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Fn { name, .. } => { let name = *name; if name.is_none() { String::from("new") } else { a_symbols_text(names, std::convert::identity(name)) } },
        _ => String::from(""),
    }
}

pub fn allocates_here(expr: &Expr, asked: &Asked<'_, '_, '_>) -> bool {
    match expr {
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_, _) => true,
        Expr::LitStr { .. } => true,
        Expr::LitInterpolated { .. } => true,
        Expr::LitChar(_, _) => true,
        Expr::LitBool(_, _) => true,
        Expr::LitNull(_) => true,
        Expr::StructLit { .. } => true,
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); a_call_that_allocates((call_path(func, asked.names)).as_deref(), asked) },
        Expr::MethodCall { method, .. } => { let method = *method; hands_back_a_plain_value(asked.names.resolve(method), asked) },
        Expr::SafeMethod { method, .. } => { let method = *method; hands_back_a_plain_value(asked.names.resolve(method), asked) },
        _ => false,
    }
}

pub(crate) fn a_call_that_allocates(path: Option<&str>, asked: &Asked<'_, '_, '_>) -> bool {
    let callee = match path { Some(__nikaia_value) => __nikaia_value, None => return false };
    is_hull(callee) || hands_back_a_plain_value(callee, asked)
}

pub fn hands_back_a_plain_value(callee: &str, asked: &Asked<'_, '_, '_>) -> bool {
    let suffix = format!("::{}", callee);
    if has_an_entry(asked.own, callee, &suffix) { return plain_in(asked.own, callee, &suffix); }
    plain_in(asked.library, callee, &suffix)
}

pub(crate) fn has_an_entry(ledger: &Ledger, callee: &str, suffix: &str) -> bool {
    if ledger.functions.contains_key(callee) { return true; }
    for key in ledger.functions.keys() { if key.ends_with(&suffix) { return true; } }
    false
}

pub(crate) fn plain_in(ledger: &Ledger, callee: &str, suffix: &str) -> bool {
    let exact = *nikaia_std::index::get(&ledger.functions, callee);
    if exact.is_some() { return a_plain_result(exact); }
    for (key, contract) in ledger.functions.iter() { if key.ends_with(&suffix) { return a_plain_result(Some(contract)); } }
    false
}

pub(crate) fn a_plain_result(contract: Option<&FnContract>) -> bool {
    let found = match contract { Some(__nikaia_value) => __nikaia_value, None => return false };
    let signature = match found.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    !result.is_unknown() && !holds_shared(result)
}

pub fn origin_reason(expr: &Expr, names: &winnow_grammar::InternerContext) -> String {
    let from = where_it_came_from(expr, names);
    format!("{}, so this analysis did not watch the allocation being made - and the count belongs to the allocation. A call handed to another thread hands its result back across one (ADR-292)", from)
}

pub(crate) fn where_it_came_from(expr: &Expr, names: &winnow_grammar::InternerContext) -> String {
    match expr {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); a_call_that_hands_it_back((call_path(func, names)).as_deref()) },
        Expr::MethodCall { method, .. } => { let method = *method; format!("`{}` hands it back", names.resolve(method)) },
        Expr::SafeMethod { method, .. } => { let method = *method; format!("`{}` hands it back", names.resolve(method)) },
        Expr::Field { name, .. } => { let name = *name; format!("it is read out of `{}`", names.resolve(name)) },
        Expr::Index { .. } => String::from("it is read out of a collection"),
        _ => String::from("it comes from an expression this analysis does not follow"),
    }
}

pub(crate) fn a_call_that_hands_it_back(path: Option<&str>) -> String {
    let callee = match path { Some(__nikaia_value) => __nikaia_value, None => return String::from("a call hands it back") };
    format!("`{}` hands it back", callee)
}

pub fn named_handle(expr: &Expr, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    match expr {
        Expr::Variable(name, _) => { let name = *name; a_handle_in_scope(names.resolve(name), scope) },
        Expr::Block(block, _) => a_handle_at_the_tail(block, names, scope),
        _ => None,
    }
}

pub(crate) fn a_handle_in_scope(name: &str, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    let ty = match *nikaia_std::index::get(&scope, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if holds_shared(ty) { return Some(name.to_owned()); }
    None
}

pub(crate) fn a_handle_at_the_tail(block: &Block, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    if block.stmts.is_empty() { return None; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(tail) => named_handle(tail, names, scope),
        _ => None,
    }
}

pub fn named_type(expr: &Expr, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    match expr {
        Expr::Variable(name, _) => { let name = *name; scope_type_name(names.resolve(name), scope) },
        _ => None,
    }
}

pub(crate) fn scope_type_name(name: &str, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    let ty = match *nikaia_std::index::get(&scope, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(without_a_view(&ty.text()))
}

pub fn walks_in_parallel(receiver: &Expr, names: &winnow_grammar::InternerContext, parallel: &collections::BTreeSet<String>) -> bool {
    match receiver {
        Expr::Variable(name, _) => { let name = *name; parallel.contains(names.resolve(name)) },
        Expr::MethodCall { receiver, method, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; a_parallel_method(names.resolve(method)) || walks_in_parallel(receiver, names, parallel) },
        _ => false,
    }
}

pub fn a_parallel_method(method: &str) -> bool {
    for one in PARALLEL.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn call_path(func: &Expr, names: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name, _) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments, _) => Some(joined_segments(segments, names)),
        _ => None,
    }
}

pub(crate) const RESULT: &str = "<result>";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SharingWalk {
    pub slots: Slots,
    pub parallel: collections::BTreeSet<String>,
    pub function: String,
    pub scope: collections::BTreeMap<String, Ty>,
    pub library_keys: collections::BTreeMap<String, String>,
    pub own_keys: collections::BTreeMap<String, String>,
}

pub fn sharing_of(program: &Program, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, crossings_are_possible: bool) -> Sharing {
    let mut walk = SharingWalk { slots: Slots::new(declared_here(asked.names, &program.items)), parallel: collections::BTreeSet::new(), function: String::from(""), scope: collections::BTreeMap::new(), library_keys: collections::BTreeMap::new(), own_keys: collections::BTreeMap::new() };
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { .. } => { sharing_function(&item.node, "", asked, holes_of, ty_of, &mut walk); },
            Item::Impl { target, methods, .. } => {
                let owner = asked.names.resolve(target.name).to_owned();
                for method in methods.iter() { sharing_function(&method.node, &owner, asked, holes_of, ty_of, &mut walk); }
            },
            Item::Struct { name, fields, is_public, .. } => {
                let is_public = *is_public; let name = *name;
                if is_public { public_fields(asked.names.resolve(name), fields, asked, ty_of, &mut walk); }
            },
            _ => { },
        }
    }
    let mut sharing = decided(&mut walk.slots);
    if !crossings_are_possible { every_count_plain(&mut sharing); }
    sharing
}

pub(crate) fn public_fields(owner: &str, fields: &[FieldDef], asked: &Asked<'_, '_, '_>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    for field in fields.iter() {
        if !field.is_public { continue; }
        let ty = ty_of(&field.ty);
        if !holds_shared(&ty) { continue; }
        let key = format!("{}.{}", owner, asked.names.resolve(field.name));
        walk.slots.note(FIELDS, &key, ty, true, false);
        walk.slots.force(FIELDS, &key, format!("`{}` is a public field of a public type, so code this build cannot see may take the value out of it and cross with it", key), Some(Fallback::PublicField));
    }
}

pub(crate) fn sharing_function(item: &Item, owner: &str, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match item {
        Item::Fn { name, args, body, ret_type, is_public, .. } => {
            let is_public = *is_public; let name = *name;
            walk.function = key_of_function((name).as_ref(), owner, asked.names);
            walk.scope = collections::BTreeMap::new();
            for arg in args.iter() {
                let ty = ty_of(&arg.ty);
                let named = asked.names.resolve(arg.name).to_owned();
                position(&named, &ty, is_public, asked, walk);
                walk.scope.insert(named, ty);
            }
            if ret_type.is_some() {
                let result = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return };
                position(RESULT, &ty_of(result), is_public, asked, walk);
            }
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        _ => { },
    }
}

pub(crate) fn position(named: &str, ty: &Ty, is_public: bool, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) {
    let function = walk.function.to_owned();
    if holds_shared(ty) {
        walk.slots.note(&function, named, ty.clone(), named == RESULT, true);
        if is_public { walk.slots.force(&function, named, published_reason(&function, named), Some(Fallback::PublicSignature)); }
    } else if is_public { for field in shared_fields(&ty.text(), asked) { walk.slots.force(FIELDS, &field, published_reason(&function, named), Some(Fallback::PublicSignature)); } }
}

pub(crate) fn sharing_block(block: &Block, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) { for stmt in block.stmts.iter() { sharing_statement(&stmt.node, asked, holes_of, ty_of, walk); } }

pub(crate) fn sharing_statement(stmt: &Stmt, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            if names.len() != 1 { return; }
            let_binding(asked.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), (ty).as_ref(), value, asked, ty_of, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        Stmt::Comptime { .. } => { },
        Stmt::Assign { target, value, .. } => {
            let target_slot = slot_of(target, asked, walk);
            if target_slot.is_some() {
                let known = nikaia_std::index::or(target_slot, || "".into());
                let source = slot_of(value, asked, walk);
                if source.is_none() {
                    let (at, named) = split_slot(&known);
                    origin_unseen(&at, &named, value, asked, walk);
                } else { walk.slots.join(&known, nikaia_std::index::or(source.as_deref(), || "")); }
            }
            sharing_expression(target, asked, holes_of, ty_of, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        Stmt::For { iter, body, .. } => {
            sharing_expression(iter, asked, holes_of, ty_of, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Stmt::While { cond, body } => {
            sharing_expression(cond, asked, holes_of, ty_of, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            hands_back(returned, asked, walk);
            sharing_expression(returned, asked, holes_of, ty_of, walk);
        },
        Stmt::Expr(value) => {
            hands_back(value, asked, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        _ => { },
    }
}

pub(crate) fn let_binding(named: String, written: Option<&Type>, value: &Expr, asked: &Asked<'_, '_, '_>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    if walks_in_parallel(value, asked.names, &walk.parallel) { walk.parallel.insert(named.to_owned()); }
    let aliased = named_handle(value, asked.names, &walk.scope);
    let ty = match binding_type(written, (aliased).as_deref(), value, asked, ty_of, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return };
    if holds_shared(&ty) {
        let function = walk.function.to_owned();
        walk.slots.note(&function, &named, ty.clone(), false, false);
        if aliased.is_some() { walk.slots.join(&slot(&function, &named), &slot(&function, nikaia_std::index::or(aliased.as_deref(), || ""))); } else {
            let source = slot_of(value, asked, walk);
            if source.is_some() { walk.slots.join(&slot(&function, &named), nikaia_std::index::or(source.as_deref(), || "")); } else if !(by_value_shared(&ty) && allocates_here(value, asked)) { origin_unseen(&function, &named, value, asked, walk); }
        }
    }
    walk.scope.insert(named, ty);
}

pub(crate) fn binding_type(written: Option<&Type>, aliased: Option<&str>, value: &Expr, asked: &Asked<'_, '_, '_>, ty_of: &impl Fn(&Type) -> Ty, scope: &collections::BTreeMap<String, Ty>) -> Option<Ty> {
    if written.is_some() { return Some(ty_of(match written { Some(__nikaia_value) => __nikaia_value, None => return None })); }
    if aliased.is_some() {
        let handle = match aliased { Some(__nikaia_value) => __nikaia_value, None => return None };
        let ty = match *nikaia_std::index::get(&scope, handle) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(ty.clone());
    }
    match value {
        Expr::StructLit { name, .. } => { let name = *name; Some(plain_type(asked.names.resolve(name))) },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); hull_written(func, args, asked) },
        _ => None,
    }
}

pub(crate) fn hull_written(func: &Expr, args: &[Expr], asked: &Asked<'_, '_, '_>) -> Option<Ty> {
    let named = match func {
        Expr::Variable(name, _) => { let name = *name; asked.names.resolve(name).to_owned() },
        _ => return None,
    };
    if !is_hull(&named) { return None; }
    if args.len() == 1 {
        let held = match literal_type(nikaia_std::index::get(&args, 0)) { Some(__nikaia_value) => __nikaia_value, None => return Some(plain_type(&named)) };
        return Some(Ty::Named { name: named, args: vec![plain_type(&held)], view: false });
    }
    Some(plain_type(&named))
}

pub(crate) fn plain_type(name: &str) -> Ty { Ty::Named { name: name.to_owned(), args: vec![], view: false } }

pub(crate) fn hands_back(value: &Expr, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) {
    let source = match slot_of(value, asked, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.slots.join(&slot(&walk.function, RESULT), &source);
}

pub(crate) fn origin_unseen(function: &str, named: &str, value: &Expr, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) { walk.slots.force(function, named, origin_reason(value, asked.names), Some(Fallback::UnseenOrigin)); }

pub(crate) fn a_crossing_reaches(named: &str, why: &str, fallback: Option<Fallback>, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) {
    let ty = match match *nikaia_std::index::get(&walk.scope, named) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    if holds_shared(&ty) {
        walk.slots.force(&walk.function, named, why.to_owned(), fallback);
        return;
    }
    for field in shared_fields(&ty.text(), asked) { walk.slots.force(FIELDS, &field, why.to_owned(), fallback); }
}

pub(crate) fn slot_of(expr: &Expr, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) -> Option<String> {
    let handle = named_handle(expr, asked.names, &walk.scope);
    if handle.is_some() { return Some(slot(&walk.function, nikaia_std::index::or(handle.as_deref(), || ""))); }
    match expr {
        Expr::Field { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; field_slot(base, asked.names.resolve(name), asked, walk) },
        _ => None,
    }
}

pub(crate) fn field_slot(base: &Expr, field: &str, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) -> Option<String> {
    let owner = match named_type(base, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let ty = match declared_field_type(&owner, field, asked) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !holds_shared(&ty) { return None; }
    let key = format!("{}.{}", owner, field);
    walk.slots.note(FIELDS, &key, ty, true, false);
    Some(slot(FIELDS, &key))
}

pub(crate) fn sharing_expression(expr: &Expr, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match expr {
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            for named in names_used_by(body, asked) {
                if a_handle_by_value(&named, &walk) { walk.slots.duplicates(&walk.function, &named, String::from("used by a `spawn` body, which takes a handle of its own")); }
                a_crossing_reaches(&named, "a `spawn` body uses it, and a task runs on a thread of its own", None, asked, walk);
            }
            sharing_expression(body, asked, holes_of, ty_of, walk);
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = call_path(func, asked.names);
            let path = nikaia_std::index::or(match callee.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || "".into());
            if path == "access_all" || path == "update_all" {
                for arg in args.iter() {
                    let handle = match named_handle(arg, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    walk.slots.held_together.push(slot(&walk.function, &handle));
                }
            }
            sharing_arguments(&SharingCall { callee, is_method: false }, args, config, asked, holes_of, ty_of, walk);
            sharing_expression(func, asked, holes_of, ty_of, walk);
        },
        Expr::MethodCall { .. } => { sharing_method(expr, asked, holes_of, ty_of, walk); },
        Expr::SafeMethod { .. } => { sharing_method(expr, asked, holes_of, ty_of, walk); },
        Expr::StructLit { name, fields, .. } => {
            let name = *name;
            let owner = asked.names.resolve(name).to_owned();
            for field in fields.iter() { struct_field(&owner, field, asked, holes_of, ty_of, walk); }
        },
        Expr::LitInterpolated { .. } => { for hole in holes_of(expr) { sharing_expression(&hole, asked, holes_of, ty_of, walk); } },
        Expr::Closure { body, .. } => {
            a_kept_lambda_uses(expr, asked, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Expr::Block(block, _) => { sharing_block(block, asked, holes_of, ty_of, walk); },
        Expr::Overlap(block, _) => { sharing_block(block, asked, holes_of, ty_of, walk); },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            sharing_expression(cond, asked, holes_of, ty_of, walk);
            sharing_block(then_branch, asked, holes_of, ty_of, walk);
            sharing_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, asked, holes_of, ty_of, walk);
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            sharing_expression(value, asked, holes_of, ty_of, walk);
            for arm in arms.iter() { sharing_expression(&arm.body, asked, holes_of, ty_of, walk); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            sharing_expression(lhs, asked, holes_of, ty_of, walk);
            sharing_expression(rhs, asked, holes_of, ty_of, walk);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); sharing_expression(expr, asked, holes_of, ty_of, walk); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); sharing_expression(inner, asked, holes_of, ty_of, walk); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); sharing_expression(inner, asked, holes_of, ty_of, walk); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); sharing_expression(expr, asked, holes_of, ty_of, walk); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); sharing_expression(base, asked, holes_of, ty_of, walk); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); sharing_expression(base, asked, holes_of, ty_of, walk); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            sharing_expression(base, asked, holes_of, ty_of, walk);
            sharing_expression(index, asked, holes_of, ty_of, walk);
        },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            sharing_expression(value, asked, holes_of, ty_of, walk);
            sharing_expression(fallback, asked, holes_of, ty_of, walk);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            sharing_expression(expr, asked, holes_of, ty_of, walk);
            sharing_block(handler, asked, holes_of, ty_of, walk);
        },
        Expr::Tuple(parts, _) => { for part in parts.iter() { sharing_expression(part, asked, holes_of, ty_of, walk); } },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            sharing_expression(start, asked, holes_of, ty_of, walk);
            sharing_expression(end, asked, holes_of, ty_of, walk);
        },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            sharing_expression(value, asked, holes_of, ty_of, walk);
            sharing_expression(count, asked, holes_of, ty_of, walk);
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { sharing_expression(item, asked, holes_of, ty_of, walk); } },
        _ => { },
    }
}

pub(crate) fn a_kept_lambda_uses(lambda: &Expr, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) {
    for named in names_used_by(lambda, asked) {
        if a_handle_by_value(&named, &walk) { walk.slots.duplicates(&walk.function, &named, String::from("used by a kept lambda, which takes a handle of its own")); }
        a_crossing_reaches(&named, "a kept lambda uses it, and a kept function may be called on any thread", None, asked, walk);
    }
}

pub(crate) fn names_used_by(expr: &Expr, asked: &Asked<'_, '_, '_>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    names_in(expr, asked.names, &mut out);
    out
}

pub(crate) fn a_handle_by_value(named: &str, walk: &SharingWalk) -> bool {
    let ty = match *nikaia_std::index::get(&walk.scope, named) { Some(__nikaia_value) => __nikaia_value, None => return false };
    by_value_shared(ty)
}

pub(crate) fn struct_field(owner: &str, field: &FieldInit, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let field_name = asked.names.resolve(field.name).to_owned();
    let value = nikaia_std::index::or(match field.value.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Expr::Variable(field.name, fresh_id()));
    let key = format!("{}.{}", owner, field_name);
    let handle = named_handle(&value, asked.names, &walk.scope);
    if handle.is_some() {
        let named = nikaia_std::index::or(handle, || "".into());
        let ty = match match *nikaia_std::index::get(&walk.scope, &named) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        walk.slots.note(FIELDS, &key, ty, true, false);
        walk.slots.join(&slot(&walk.function, &named), &slot(FIELDS, &key));
    } else {
        let declared = declared_field_type(owner, &field_name, asked);
        if declared.is_some() && holds_shared(nikaia_std::index::or(declared.as_ref(), || &Ty::Unknown)) {
            walk.slots.note(FIELDS, &key, nikaia_std::index::or(declared, || Ty::Unknown), true, false);
            let source = slot_of(&value, asked, walk);
            if source.is_none() { origin_unseen(FIELDS, &key, &value, asked, walk); } else { walk.slots.join(nikaia_std::index::or(source.as_deref(), || ""), &slot(FIELDS, &key)); }
        }
    }
    sharing_expression(&value, asked, holes_of, ty_of, walk);
}

pub(crate) fn sharing_method(call: &Expr, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let (receiver, method, args, config) = match call {
        Expr::MethodCall { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, asked.names.resolve(method).to_owned(), args, config) },
        Expr::SafeMethod { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, asked.names.resolve(method).to_owned(), args, config) },
        _ => return,
    };
    if method == "get" && args.is_empty() { a_copy_out_of_the_lock(receiver, asked, walk); }
    if a_parallel_method(&method) || method == "spawn" || walks_in_parallel(receiver, asked.names, &walk.parallel) {
        let why = format!("a lambda handed to `{}` uses it, and that lambda runs on a thread the program asked for", method);
        for arg in args.iter() { for named in names_used_by(arg, asked) { a_crossing_reaches(&named, &why, None, asked, walk); } }
    }
    sharing_arguments(&SharingCall { callee: Some(method), is_method: true }, args, config, asked, holes_of, ty_of, walk);
    sharing_expression(receiver, asked, holes_of, ty_of, walk);
}

pub(crate) fn a_copy_out_of_the_lock(receiver: &Expr, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) {
    let handle = match named_handle(receiver, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return };
    let ty = match *nikaia_std::index::get(&walk.scope, &handle) { Some(__nikaia_value) => __nikaia_value, None => return };
    let held = match held_that_does_not_copy(ty) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.slots.copies.push((slot(&walk.function, &handle), format!("`{}.get()` copies the whole `{}` out of the lock", handle, held)));
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct SharingCall {
    pub(crate) callee: Option<String>,
    pub(crate) is_method: bool,
}

pub(crate) fn sharing_arguments(called: &SharingCall, args: &[Expr], config: &[ConfigArg], asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let described = parameters_of((called.callee).as_deref(), asked, &mut walk.own_keys, &mut walk.library_keys);
    for at in 0..args.len() as i64 {
        let arg = nikaia_std::index::get(&args, nikaia_std::index::at(at));
        let handle = named_handle(&arg, asked.names, &walk.scope);
        if handle.is_none() {
            an_argument_that_is_not_a_handle(called, (described).as_ref(), at, &arg, asked, walk);
            a_lambda_handed_on((described).as_ref(), at, &arg, asked, holes_of, ty_of, walk);
            continue;
        }
        let __keep_63484 = nikaia_std::tether::Keep::new();
        a_handle_handed_on(called, (described).as_ref(), at, nikaia_std::index::or(handle.as_deref(), || ""), walk);
    }
    for setting in config.iter() {
        let why = format!("it is handed to `{}` as the option `{}`, and no contract says what happens to a `Shared` in an option", nikaia_std::index::or(match called.callee.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "the callee".into()), asked.names.resolve(setting.name));
        for named in names_used_by(&setting.value, asked) { a_crossing_reaches(&named, &why, Some(Fallback::UncoveredArgument), asked, walk); }
        sharing_expression(&setting.value, asked, holes_of, ty_of, walk);
    }
}

pub(crate) fn a_lambda_handed_on(described: Option<&Described>, at: i64, arg: &Expr, asked: &Asked<'_, '_, '_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match arg {
        Expr::Closure { body, .. } => {
            if described.is_some() && a_kept_position(match described { Some(__nikaia_value) => __nikaia_value, None => return }, at) { a_kept_lambda_uses(arg, asked, walk); }
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        _ => { sharing_expression(arg, asked, holes_of, ty_of, walk); },
    }
}

pub(crate) fn a_kept_position(known: &Described, at: i64) -> bool { at < known.params.len() as i64 && known.keeps.contains(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0) }

pub(crate) fn an_argument_that_is_not_a_handle(called: &SharingCall, described: Option<&Described>, at: i64, arg: &Expr, asked: &Asked<'_, '_, '_>, walk: &mut SharingWalk) {
    if described.is_none() {
        let why = unseen((called.callee).as_deref());
        for named in names_used_by(arg, asked) { a_crossing_reaches(&named, &why, Some(unseen_kind(called)), asked, walk); }
        return;
    }
    let known = match described { Some(__nikaia_value) => __nikaia_value, None => return };
    if at >= known.params.len() as i64 { return; }
    let param = nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0.to_owned();
    if !by_value_shared(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).1) { return; }
    let source = match slot_of(arg, asked, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    let (owner, named) = split_slot(&source);
    walk.slots.duplicates(&owner, &named, handed_on_to(&known.key, &param));
    walk.slots.join(&source, &slot(&known.key, &param));
}

pub(crate) fn a_handle_handed_on(called: &SharingCall, described: Option<&Described>, at: i64, handle: &str, walk: &mut SharingWalk) {
    let function = walk.function.to_owned();
    if described.is_none() {
        walk.slots.force(&function, handle, unseen((called.callee).as_deref()), Some(unseen_kind(called)));
        return;
    }
    let known = match described { Some(__nikaia_value) => __nikaia_value, None => return };
    if at >= known.params.len() as i64 {
        let callee = nikaia_std::index::or(match called.callee.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "the callee".into());
        walk.slots.force(&function, handle, format!("`{}` takes it in a position no contract describes", callee), Some(Fallback::UncoveredArgument));
        return;
    }
    let param = nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0.to_owned();
    if by_value_shared(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).1) { walk.slots.duplicates(&function, handle, handed_on_to(&known.key, &param)); }
    walk.slots.join(&slot(&function, handle), &slot(&known.key, &param));
}

pub(crate) fn unseen_kind(called: &SharingCall) -> Fallback {
    if called.is_method { return Fallback::UnseenMethod; }
    Fallback::UnseenCall
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Described {
    pub(crate) key: String,
    pub(crate) params: Vec<(String, Ty)>,
    pub(crate) keeps: Vec<String>,
}

pub(crate) fn parameters_of(callee: Option<&str>, asked: &Asked<'_, '_, '_>, own_keys: &mut collections::BTreeMap<String, String>, library_keys: &mut collections::BTreeMap<String, String>) -> Option<Described> {
    let named = match callee { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !own_keys.contains_key(named) { own_keys.insert(named.to_owned(), nikaia_std::index::or(described_key(named, asked.own), || "".into())); }
    let in_own = match *nikaia_std::index::get(&own_keys, named) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if in_own != "" { return described_by(in_own, asked.own); }
    if !library_keys.contains_key(named) { library_keys.insert(named.to_owned(), nikaia_std::index::or(described_key(named, asked.library), || "".into())); }
    let in_library = match *nikaia_std::index::get(&library_keys, named) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if in_library == "" { return None; }
    described_by(in_library, asked.library)
}

pub(crate) fn described_key(callee: &str, ledger: &Ledger) -> Option<String> {
    if ledger.functions.contains_key(callee) { return Some(callee.to_owned()); }
    let suffix = format!("::{}", callee);
    for (one, _) in ledger.functions.iter() { if one.ends_with(&suffix) { return Some(one.to_owned()); } }
    None
}

pub(crate) fn described_by(key: &str, ledger: &Ledger) -> Option<Described> {
    let contract = match *nikaia_std::index::get(&ledger.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut params: Vec<(String, Ty)> = vec![];
    let mut first = true;
    for (name, ty) in signature.params.iter() {
        if !(first && name == "self") { params.push((name.to_owned(), ty.clone())); }
        first = false;
    }
    Some(Described { key: key.to_owned(), params, keeps: contract.keeps.to_owned() })
}

